import { renderHook } from '@testing-library/react-hooks';

import { EVENT_ACTIONS } from '@proton/shared/lib/constants';

import { useEventManager } from '../../hooks';
import { interval, maxPollingSteps, usePollEvents } from './usePollEvents';

jest.mock('../../hooks', () => ({ useEventManager: jest.fn() }));

const flush = async () => {
    await Promise.resolve();
    await Promise.resolve();
};

describe('usePollEvents', () => {
    const call = jest.fn().mockResolvedValue(undefined);
    const unsubscribe = jest.fn();
    let handler: (event: Record<string, any>) => void;
    const subscribe = jest.fn((listener) => {
        handler = listener;
        return unsubscribe;
    });

    beforeEach(() => {
        jest.useFakeTimers();
        jest.clearAllMocks();
        call.mockResolvedValue(undefined);
        (useEventManager as jest.Mock).mockReturnValue({ call, subscribe });
    });

    afterEach(() => {
        jest.useRealTimers();
    });

    it('calls once per interval and stops after five attempts without a subscription', async () => {
        const { result } = renderHook(() => usePollEvents());
        const done = result.current();
        expect(subscribe).not.toHaveBeenCalled();

        for (let attempt = 1; attempt <= maxPollingSteps; attempt++) {
            jest.advanceTimersByTime(interval - 1);
            await flush();
            expect(call).toHaveBeenCalledTimes(attempt - 1);
            jest.advanceTimersByTime(1);
            await flush();
            expect(call).toHaveBeenCalledTimes(attempt);
        }
        await done;
        jest.advanceTimersByTime(interval);
        expect(call).toHaveBeenCalledTimes(maxPollingSteps);
    });

    it('ignores unrelated updates, then stops and unsubscribes on a matching update', async () => {
        const { result } = renderHook(() => usePollEvents());
        const done = result.current('PaymentMethods', EVENT_ACTIONS.CREATE);
        handler({ Other: [{ Action: EVENT_ACTIONS.CREATE }] });
        handler({ PaymentMethods: [{ Action: EVENT_ACTIONS.UPDATE }] });
        jest.advanceTimersByTime(interval);
        await flush();
        expect(call).toHaveBeenCalledTimes(1);
        handler({ PaymentMethods: [{ Action: EVENT_ACTIONS.CREATE }] });
        await done;
        expect(unsubscribe).toHaveBeenCalledTimes(1);
        handler({ PaymentMethods: [{ Action: EVENT_ACTIONS.CREATE }] });
        jest.advanceTimersByTime(interval * maxPollingSteps);
        expect(call).toHaveBeenCalledTimes(1);
        expect(unsubscribe).toHaveBeenCalledTimes(1);
    });

    it('unsubscribes after the last attempt and ignores late events', async () => {
        const { result } = renderHook(() => usePollEvents());
        const done = result.current('PaymentMethods', EVENT_ACTIONS.CREATE);
        for (let attempt = 0; attempt < maxPollingSteps; attempt++) {
            jest.advanceTimersByTime(interval);
            await flush();
        }
        await done;
        expect(unsubscribe).toHaveBeenCalledTimes(1);
        handler({ PaymentMethods: [{ Action: EVENT_ACTIONS.CREATE }] });
        jest.advanceTimersByTime(interval);
        expect(call).toHaveBeenCalledTimes(maxPollingSteps);
    });
});
EOF
